 showModal('trialResult',result.newBest?'NIEUW PERSOONLIJK RECORD':'TIJDPROEF VOLTOOID',record.arenaName,`<div class="trial-result"><small>${TRIAL_TIERS[record.tier-1].name.toUpperCase()} · ${record.kills} VIJANDEN</small><strong>${trialTime(record.elapsedMs)}</strong><p>${result.previousMs?result.newBest?trialTime(result.previousMs-record.elapsedMs)+' sneller dan je vorige record':'Persoonlijk record: '+trialTime(result.previousMs):'Je eerste record op deze moeilijkheid.'}</p></div><div class="trial-reward">${gearCard(item,'VERDIEND · ZELF UITRUSTEN IN HET KAMP')}<p>+${result.reward} schroot · +${result.xp} XP · ${record.tier<3?'Volgende moeilijkheid vrijgespeeld.':'Meestergraad voltooid.'}</p></div><p id="share-result-status">Je resultaat wordt in deze browser bewaard.</p>`,[{label:'Terug naar Horizonpost',run:()=>{engine.returnFromChallenge();hideModal();renderer.reset(s.player,s.area);save();}},{label:s.player.inventory.length>=48?'Rugzak vol · eerst legen':'Nog een poging',secondary:true,disabled:s.player.inventory.length>=48,run:()=>{engine.restartChallenge();hideModal();renderer.reset(s.player,s.area);save();}},{label:'Kopieer resultaat om te delen',secondary:true,run:async()=>{const text=recordText(record);try{await navigator.clipboard.writeText(text);$('share-result-status').textContent='Resultaat gekopieerd. Je kunt het zelf ergens delen.';}catch{$('share-result-status').innerHTML='<label>Kopieer deze tekst<textarea readonly>'+escape(text)+'</textarea></label>';$('share-result-status').querySelector('textarea')?.select?.();}}}]);
