 showModal('pause',engine.isLan?'LAN · DE WERELD LOOPT DOOR':'EXPEDITIE GEPAUZEERD','De horizon wacht.',`<p>${escape(AREA_BY_ID[engine.state.area].name)} · ${timeLabel(engine.state.runTime)} onderweg</p><p>${engine.isLan?'Je partner speelt verder terwijl je dit menu bekijkt. Ga voor rustig beheren naar de veilige post.':'Je voortgang wordt automatisch in deze browser bewaard.'}</p>`,[{label:'Verder',run:hideModal},{label:'Instellingen',secondary:true,run:showSettings},...(settings.lore?[{label:'Verhaal & doel · L',secondary:true,run:()=>showJourney()}]:[]),...(engine.challengeBuildLocked()?[{label:'Tijdproef verlaten · Horizonpost',secondary:true,run:()=>{engine.returnFromChallenge();hideModal();renderer.reset(engine.state.player,engine.state.area);save();}}]:[]),{label:'Besturing',secondary:true,run:showHelp},{label:'Titelmenu',secondary:true,run:()=>{save();if(engine.isLan)engine.disconnect();hideModal();started=false;$('cover').hidden=false;refreshContinue();audio.pause();}}]);save();
