function persistSettings(){try{localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings));}catch{}}
function applyQuestPanel(){const collapsed=touchMode?!touchQuestOpen:settings.questCollapsed,button=$('quest-toggle');$('quest-panel').classList.toggle('collapsed',collapsed);$('quest-content').hidden=collapsed;button.textContent=collapsed?'Gebied':'×';button.setAttribute('aria-expanded',String(!collapsed));button.setAttribute('aria-label',collapsed?'Gebiedstekst tonen':'Gebiedstekst verbergen');button.title=collapsed?'Gebiedstekst tonen':'Gebiedstekst verbergen';}
function applySettings(){syncTouchMode();audio.setVolumes(settings.music,settings.effects);renderer.settings={...settings,touchUI:touchMode};renderer.performanceScale=settings.quality==='low'?.7:1;renderer.frameSamples=[];renderer.healthyWindows=0;if(renderer.ready)renderer.resize();document.documentElement?.style.setProperty('--aim-scale',settings.cursor);applyQuestPanel();$('journey-button').hidden=!settings.lore;$('quest-purpose').hidden=!settings.lore;if(!settings.lore){journey.disable();$('journey-peek').hidden=true;}persistSettings();}
