 const open=engine.testModeEnabled();
 showModal('test','GEBIEDEN TESTEN · F8',open?'Alle routes beschikbaar':'Testmodus openen',open?`<p>Reis rechtstreeks naar elk gebied. Gevechten blijven actief. Zolang testmodus actief is, staat automatisch opslaan uit.</p><label>Gebied<select id="test-area">${AREAS.map(a=>`<option value="${a.id}" ${a.id===engine.state.area?'selected':''}>${escape(a.name)}</option>`).join('')}</select></label>`:'<label>Toegangscode<input id="test-code" type="password" autocomplete="off"></label><p id="test-error" role="status"></p>',open?[{label:'Reis naar gebied',run:()=>{if(engine.testTravel($('test-area').value)){hideModal();renderer.reset(engine.state.player,engine.state.area);}}},{label:'Testmodus sluiten',secondary:true,run:()=>{engine.lockTestMode();hideModal();}},{label:'Verder spelen',secondary:true,run:hideModal}]:[{label:'Open testmodus',run:()=>{if(engine.unlockTestMode($('test-code').value)){if(!engine.isLan)showTestMode();else $('test-error').textContent='Code wordt gecontroleerd…';}else $('test-error').textContent='Onjuiste code.';}},{label:'Terug',secondary:true,run:hideModal}]);
