function showSettings(){
 const perf=frameTelemetry.report(),readout=perf?`${perf.fps} FPS · 95% van de frames binnen ${perf.p95Ms} ms · ${perf.slowPercent}% boven 25 ms`:'Wordt gemeten zodra je enkele seconden speelt.';
 showModal('settings','SPEL, BEELD & GELUID','Instellingen',`<div class="settings-grid">${[['music','Muziek'],['effects','Effectgeluid'],['shake','Schermschok']].map(([k,label])=>`<label>${label}<output id="setting-value-${k}">${Math.round(settings[k]*100)}%</output><input data-setting="${k}" type="range" min="0" max="100" value="${Math.round(settings[k]*100)}" aria-label="${label}"></label>`).join('')}<label>Verhaal onderweg<select data-setting="lore" aria-label="Verhaal onderweg"><option value="on" ${settings.lore?'selected':''}>Aan · verhaal bij eerste bezoek</option><option value="off" ${!settings.lore?'selected':''}>Uit · direct spelen</option></select></label><label>Beeldkwaliteit<select data-setting="quality"><option value="auto" ${settings.quality==='auto'?'selected':''}>Automatisch</option><option value="high" ${settings.quality==='high'?'selected':''}>Hoog</option><option value="low" ${settings.quality==='low'?'selected':''}>Licht · minder renderpixels</option></select></label><label>Cameraafstand<select data-setting="camera">${CAMERA_ZOOMS.map(z=>`<option value="${z}" ${settings.camera===z?'selected':''}>${Math.round(z*100)}%${z===1.15?' · standaard':z<1?' · verder weg':''}</option>`).join('')}</select></label><label>Richtcursor<select data-setting="cursor"><option value="1" ${settings.cursor===1?'selected':''}>Normaal</option><option value="1.4" ${settings.cursor===1.4?'selected':''}>Groter</option></select></label><label>Besturing<select data-setting="controls"><option value="auto" ${settings.controls==='auto'?'selected':''}>Automatisch · laatst gebruikt</option><option value="controller" ${settings.controls==='controller'?'selected':''}>Controller</option><option value="keyboard" ${settings.controls==='keyboard'?'selected':''}>Toetsenbord & muis</option><option value="touch" ${settings.controls==='touch'?'selected':''}>Aanraakscherm · Android</option></select></label><label>Controller · dode zone<output id="setting-value-deadzone">${Math.round(settings.deadzone*100)}%</output><input data-setting="deadzone" type="range" min="10" max="35" value="${Math.round(settings.deadzone*100)}" aria-label="Dode zone controller"></label></div><p class="menu-intro"><b>Android / touch:</b> wordt automatisch herkend. Beweeg links en houd de aanvalsknop vast voor automatisch richten. Tik op een spreuk voor automatische plaatsing, of sleep vanaf de spreuk en laat los om zelf te richten. Rechtop staan drie slots links en drie rechts. Je stelt ze samen met je rechter ability in via het spreukenmenu. Ontwijken, verband, antidotum en kernpuls hebben eigen knoppen. Rechtop is de gewone telefoonindeling; liggend blijft ook beschikbaar. ⛶ opent volledig scherm.</p><p class="menu-intro">Controller: linker stick bewegen, rechter stick richten, RT hoofdaanval, LT rechter ability. A interactie, B ontwijken, X verband, Y kernpuls, RB antidotum. D-pad: slots 1–4; LB + omhoog/rechts: 5–6. Stick indrukken: rugzak / skills. LB + A: kaart; Menu of LB + RB: pauze. In menu’s: D-pad kiezen, A bevestigen, B terug; links/rechts wijzigt een keuzelijst of schuif, rechter stick scrollt.</p><p class="menu-intro">Je instellingen blijven in deze browser bewaard. Automatische kwaliteit verlaagt de resolutie bij trage frames en herstelt deze bij soepel spel. Hoog geeft meer detail. Cameraafstand heeft zes standen; 115% is de standaard.</p><div class="performance-readout"><b>Laatste spelmoment</b><p>${readout}</p><small>Gemeten frames in jouw browser; menu’s en het titelbeeld tellen niet mee.</small></div>`,[{label:'Verder spelen',run:hideModal},...(started?[{label:'Gebieden testen · F8',secondary:true,run:showTestMode}]:[])]);
 $('modal-body').querySelectorAll('[data-setting]').forEach(el=>el.addEventListener(el.type==='range'?'input':'change',()=>{const k=el.dataset.setting;settings=normalizeSettings({...settings,[k]:['music','effects','shake','deadzone'].includes(k)?Number(el.value)/100:k==='lore'?el.value==='on':el.value});if($('setting-value-'+k))setText($('setting-value-'+k),Math.round(settings[k]*100)+'%');applySettings();}));
}
function recipeCards(p){return `<h3>Bijzondere recepten <small>1200 schroot per stuk</small></h3><p class="menu-intro">${p.uniqueBlueprints?'Sera heeft deze voorraad vrijgegeven. Elk onderdeel kan één keer worden gebouwd; je rust het daarna zelf uit.':'Voltooi Sera’s Sporencontract in Vrijhaven om deze recepten vrij te spelen.'}</p><div class="unique-recipes">${Object.entries(UNIQUE_ITEMS).filter(([id,u])=>!u.chase).map(([id,u])=>`<button data-recipe="${id}" ${p.uniqueBlueprints&&p.level>=8&&p.scrap>=1200&&p.inventory.length<48&&!(p.uniquePurchased||[]).includes(id)?'':'disabled'}><img src="assets/items/${u.art}.webp" alt=""><strong>${u.name}</strong><p>${u.text}</p><small>${(p.uniquePurchased||[]).includes(id)?'AL GEBOUWD':p.level<8?'VANAF NIVEAU 8':'1200 SCHROOT · '+SLOT_NAMES[u.slot]}</small></button>`).join('')}</div>`;}

