 const action=document.createElement('button');action.className='primary';action.dataset.quarterQuest=q?.status||'new';action.textContent=q?.status==='ready'?'Open Lindes atelier · +100 schroot':q?'De wijken verder verkennen':'Neem De verloren wijken aan';action.disabled=q?.status==='completed';action.addEventListener('click',()=>{if(q?.status==='ready'){if(engine.claimQuarterQuest()){engine.state.destination='hidden-atelier';closeJournal();save();}}else if(q||engine.acceptQuarterQuest()){engine.state.destination=q?.seen.includes('rain-compass')?'quiet-apartments':'rain-garden';engine.syncStoryPortals();closeJournal();save();}});$('modal-actions').prepend(action);
