function showExplorationDiscovery(id){const point=engine.quarterPoint(id);if(!point)return;const q=engine.quarterQuest(),bonus=point.scrap?'+'+point.scrap+' schroot':point.bandage?'Eén voorraadrol geborgen':point.required?'Questvondst bewaard · geen rugzakplek nodig':'Toegevoegd aan je veldlog';showModal('exploration','VRIJHAVEN · ONTDEKKING',point.name,`<div class="discovery-story"><img src="assets/items/${point.art}.webp" alt=""><p>${escape(point.body)}</p></div><p class="quest-reward">${bonus}</p>${q?.status==='ready'?'<p>Je hebt beide vondsten. Breng ze naar Milo in Vrijhaven om het atelier te openen.</p>':''}`,[{label:'Verder verkennen',run:()=>{if(point.required)engine.state.destination=q.status==='ready'?'highway':'quiet-apartments';closeJournal();}}]);}
