 showModal('atelier','VRIJGESPEELD · SPECIALIST',LINDE.name,atelierBody(engine,slot),[{label:'Verder verkennen',run:closeJournal},{label:'Rugzak & uitrusting',secondary:true,run:()=>{engine.closeModal();hideModal();showEquipment();}}],view);
