 showModal('quest',n.name,d.title,`<div class="city-dialogue"><img src="assets/items/npc-${id}.webp" alt="${escape(n.name)}"><div><p>${escape(status==='completed'?'Bedankt. Met jouw hulp kan onze volgende ploeg weer op pad.':status==='ready'?d.ready:status==='active'?d.active:d.intro)}</p>${status!=='completed'?'<p class="quest-reward">'+escape(d.reward)+'</p>':''}${id==='milo'&&status==='active'?'<small>'+q.seen.length+' / 3 plekken verkend</small>':''}</div></div>`,[...(!status?[{label:'Opdracht aannemen',run:()=>{if(engine.acceptCityQuest(id)){closeJournal();save();}}}]:status==='ready'?[{label:'Beloning ophalen',disabled:id==='ilya'&&engine.state.player.inventory.length>=48,run:()=>{if(engine.claimCityQuest(id)){closeJournal();save();}}}]:[]),{label:'Verder verkennen',secondary:true,run:closeJournal}]);
