 const questLines=[];if(s.world.adventure)questLines.push('Berging · '+s.world.adventure.claimed.length+'/3 onderdelen · '+(s.world.sideDone?'terugpoort open':'F bij een vrijgemaakt punt'));const sideQuest=s.quests?.noodstroom;if(sideQuest&&sideQuest.status!=='completed')questLines.push(sideQuest.status==='ready'?'Noodstroom · terug naar Nora':'Noodstroom · berg de meetspoel');for(const [id,q]of Object.entries(s.quests||{}))if(CITY_DIALOGUES[id]&&q.status!=='completed')questLines.push(CITY_DIALOGUES[id].title+(q.status==='ready'?' · beloning ophalen':id==='milo'?' · '+q.seen.length+'/3':''));const quarters=engine.quarterQuest();if(quarters&&quarters.status!=='completed')questLines.push('De verloren wijken · '+(quarters.status==='ready'?'lever beide vondsten bij Milo in':(quarters.seen.includes('rain-compass')?'✓':'○')+' regenkompas · '+(quarters.seen.includes('atelier-key')?'✓':'○')+' bergingssleutel'));$('side-quest').hidden=!questLines.length;setText($('side-quest'),questLines.join('\n'));
