 const nk=s.notices.map(n=>n.text).join('|');if(nk!==noticeKey){noticeKey=nk;$('notices').innerHTML=s.notices.slice(0,2).map(n=>`<div style="color:${n.color}">${escape(n.text)}</div>`).join('');}
