function updateController(now,delta){
 const previous=controllerState.active;controllerState=controller.poll(globalThis.navigator,{controls:settings.controls,deadzone:settings.deadzone,context:playable()?'game':'menu',hidden:document.hidden},now);
 const hint=$('controller-status');hint.hidden=!(controllerState.active||settings.controls==='controller');if(!hint.hidden)setText(hint,!controllerState.connected?controllerState.reason:modalKind||!started?'CONTROLLER · D-pad kiezen · A bevestigen · B terug · rechter stick scrollen':'RT aanval · LT ability · A interactie · B ontwijk · LB + RB menu');
 document.documentElement?.classList.toggle('controller-active',controllerState.active);syncTouchMode();
 if(controllerState.lost&&playable()){clearInput();pauseMenu();engine.notice('Controller losgekoppeld · sluit aan of kies toetsenbord & muis');}
 if(controllerState.active&&!previous){clearInput();pointer.active=false;}
 if(!loaded||document.hidden)return;
 if(modalKind||!started){const root=modalKind?$('modal-layer'):$('cover');if(controllerState.active&&!menuControls(root).includes(document.activeElement))menuControls(root)[0]?.focus();if(controllerState.nav)focusMenu(root,document,controllerState.nav);if(controllerState.accept){audio.start();confirmMenu(root,document);}if((controllerState.back||controllerState.pause)&&modalKind&&!$('modal-close').hidden)closeJournal();if(modalKind&&controllerState.scroll)$('modal-layer').querySelector('.modal').scrollTop+=controllerState.scroll*delta*800;return;}
 if(controllerState.pause){pauseMenu();return;}
 if(!playable())return;
 for(const name of controllerState.actions){if(!playable())break;if(name==='equipment')showEquipment();else if(name==='skills')showSkills();else if(name==='map')showAtlas();else if(name==='command')engine.commandCompanions(target());else if(name==='quest')$('quest-toggle').click();else if(name==='interact'&&engine.isLan&&engine.state.coop?.travel&&!engine.state.coop.travel.accepted.includes(engine.state.coop.self))engine.acceptTravel();else action(name);}
}
